WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_cr_overlap'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '起点终点重合', 'kp-trv-cr-overlap', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "起点终点重合问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "两人何时在【起跑线】再次相遇？必须找两人单圈时间的最小公倍数！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“两人同地起跑，甲跑一圈要2分钟，乙跑一圈要3分钟。问两人多久后再次在起跑线相遇？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "在起跑线相遇，意味着甲跑了整数圈，乙也跑了整数圈。所以花费的总时间，必须既是甲跑一圈时间的倍数，也是乙跑一圈时间的倍数。"}]}, {"type": "katexBlock", "attrs": {"content": "T_{起跑线相遇} = LCM(T_{甲一圈}, T_{乙一圈})"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[算出甲跑一圈的时间 Ta] --> B[算出乙跑一圈的时间 Tb]\nB --> C[求 Ta 和 Tb 的最小公倍数]\nC --> D[这个公倍数就是他们在起点重逢的时间]"}}]}$$ AS jsonb), NULL, '起点终点重合的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "起点终点重合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_cr_overlap", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
